            "blocking_clause": blocking_clause,
        }
        return self._request("POST", "/escalations", json_body=body)

    def audit(self) -> dict:
        return self._request("GET", "/_audit")

    def reset(self) -> dict:
        return self._request("POST", "/_reset")

